// Consume acknowledged GT911 reports. A gesture and a button tap cannot be
// generated by the same touch. Changes are committed after release debounce.
module touch_ui_controller #(
    parameter CLK_HZ=25000000,
    parameter SWAP_XY=0,
    parameter FLIP_X=0,
    parameter FLIP_Y=0,
    parameter RELEASE_MS=30,
    parameter AUTO_HIDE_MS=3000
)(
    input wire I_clk, I_rst_n,
    input wire I_report_valid,
    input wire [3:0] I_contacts,
    input wire [15:0] I_x, I_y,
    output reg O_menu_visible,
    output reg O_select_valid,
    output reg [1:0] O_select_mode
);
    localparam IDLE=0, TRACK=1, SETTLE=2, BLOCK=3;
    localparam RELEASE_CYCLES=(CLK_HZ/1000)*RELEASE_MS;
    localparam AUTO_CYCLES=(CLK_HZ/1000)*AUTO_HIDE_MS;
    reg [1:0] state;
    reg [31:0] track_age, release_age, menu_age;
    reg [15:0] start_x,start_y,last_x,last_y;
    reg menu_at_start, moved20, moved80, cancel_action;

    wire [15:0] raw_x=SWAP_XY ? I_y : I_x;
    wire [15:0] raw_y=SWAP_XY ? I_x : I_y;
    wire coord_ok=(raw_x<16'd1024 && raw_y<16'd600);
    wire [15:0] x=FLIP_X ? 16'd1023-raw_x : raw_x;
    wire [15:0] y=FLIP_Y ? 16'd599-raw_y : raw_y;
    wire [15:0] sample_dx=(x>=start_x) ? x-start_x : start_x-x;
    wire [15:0] sample_dy=(y>=start_y) ? y-start_y : start_y-y;
    wire [15:0] final_dx=(last_x>=start_x) ? last_x-start_x : start_x-last_x;
    wire swipe_up=(start_y>=last_y && start_y-last_y>=16'd100);
    wire swipe_down=(last_y>=start_y && last_y-start_y>=16'd80);
    wire tap_ok=!moved20 && final_dx<=16'd20;
    wire start_hit,end_hit;
    wire [1:0] start_mode,end_mode;
    touch_mode_select u_start_button (
        .I_press(1'b1),.I_contacts(4'd1),.I_x(start_x),.I_y(start_y),
        .O_valid(start_hit),.O_mode(start_mode));
    touch_mode_select u_end_button (
        .I_press(1'b1),.I_contacts(4'd1),.I_x(last_x),.I_y(last_y),
        .O_valid(end_hit),.O_mode(end_mode));

    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) begin
            state<=IDLE; track_age<=0; release_age<=0; menu_age<=0;
            start_x<=0;start_y<=0;last_x<=0;last_y<=0;
            menu_at_start<=0;moved20<=0;moved80<=0;cancel_action<=0;
            O_menu_visible<=0;O_select_valid<=0;O_select_mode<=0;
        end else begin
            O_select_valid<=0;
            // Timeout only while no finger is being tracked.
            if(state==IDLE && O_menu_visible && !I_report_valid) begin
                if(menu_age>=AUTO_CYCLES-1) begin
                    O_menu_visible<=0;menu_age<=0;
                end else menu_age<=menu_age+1'b1;
            end
            case(state)
            IDLE: if(I_report_valid) begin
                if(I_contacts==4'd1 && coord_ok) begin
                    start_x<=x;start_y<=y;last_x<=x;last_y<=y;
                    menu_at_start<=O_menu_visible;
                    moved20<=0;moved80<=0;track_age<=0;release_age<=0;
                    menu_age<=0;state<=TRACK;
                end else if(I_contacts!=0) state<=BLOCK;
            end
            TRACK: begin
                if(track_age<CLK_HZ) track_age<=track_age+1'b1;
                if(I_report_valid) begin
                    if(I_contacts==4'd1 && coord_ok) begin
                        last_x<=x;last_y<=y;
                        if(sample_dx>16'd20 || sample_dy>16'd20) moved20<=1;
                        if(sample_dx>16'd80) moved80<=1;
                    end else if(I_contacts==0) begin
                        release_age<=0;cancel_action<=0;state<=SETTLE;
                    end else state<=BLOCK;
                end
            end
            BLOCK: if(I_report_valid && I_contacts==0) begin
                release_age<=0;cancel_action<=1;state<=SETTLE;
            end
            SETTLE: begin
                if(I_report_valid && I_contacts!=0) begin
                    release_age<=0;
                    if(!cancel_action && I_contacts==4'd1 && coord_ok) begin
                        last_x<=x;last_y<=y;state<=TRACK;
                        if(sample_dx>16'd20 || sample_dy>16'd20) moved20<=1;
                        if(sample_dx>16'd80) moved80<=1;
                    end else state<=BLOCK;
                end else if(release_age>=RELEASE_CYCLES-1) begin
                    state<=IDLE;
                    if(!cancel_action) begin
                        if(!menu_at_start) begin
                            if(start_y>=16'd500 && swipe_up && !moved80 &&
                               final_dx<=16'd80 && track_age<CLK_HZ) begin
                                O_menu_visible<=1;menu_age<=0;
                            end
                        end else if((start_y<=16'd520 && swipe_down &&
                                      !moved80 && final_dx<=16'd80) ||
                                    (start_y<16'd450 && tap_ok)) begin
                            O_menu_visible<=0;menu_age<=0;
                        end else if(tap_ok && start_hit && end_hit &&
                                    start_mode==end_mode) begin
                            O_select_mode<=start_mode;O_select_valid<=1;
                            menu_age<=0;
                        end
                    end
                end else release_age<=release_age+1'b1;
            end
            default: state<=IDLE;
            endcase
        end
    end
endmodule
